INSERT INTO categories (id, name, description) VALUES ('railway-exam', 'Railway Exam', 'General Awareness, Reasoning, Numerical Ability, and General Science practice for Indian Railways recruitment exams (RRB NTPC / Group D style).');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('railway-exam-bank', NULL, 'Railway Exam Prep', 'railway', 'shared', '2026-11-12T13:17:07.100Z', '2026-11-12T13:17:07.100Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('railway-exam-bank', 'railway-exam');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q01', 'railway-exam-bank', 'General Awareness', 0, 0, 'Who is known as the "Father of the Indian Railways"?', 'Lord Dalhousie is credited as the father of Indian Railways — as Governor-General of India, he laid the foundational policy for India''s rail network in his 1853 Railway Minute, leading to the first passenger train running from Bombay to Thane in 1853.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q02', 'railway-exam-bank', 'General Awareness', 0, 1, 'Which is the longest railway platform in the world, and where is it located?', 'Gorakhpur railway station in Uttar Pradesh, India has the title of the world''s longest railway platform, at approximately 1,366.33 metres.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q03', 'railway-exam-bank', 'General Awareness', 0, 2, 'What does "CRIS" stand for in the context of Indian Railways, and what is its function?', 'CRIS stands for Centre for Railway Information Systems — it is the IT arm of Indian Railways, responsible for systems like the passenger reservation system (PRS), freight operations information system (FOIS), and the National Train Enquiry System (NTES).', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q04', 'railway-exam-bank', 'General Awareness', 0, 3, 'Which railway zone is headquartered in Hajipur, and what is notable about it?', 'East Central Railway, headquartered in Hajipur, Bihar, is notable for being the only railway zone headquartered outside a state capital.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q05', 'railway-exam-bank', 'General Awareness', 0, 4, 'What is the significance of April 16, 1853 in Indian Railway history?', 'On April 16, 1853, the first passenger train in India ran a 34 km stretch from Bori Bunder (Bombay) to Thane, hauled by three steam locomotives — marking the formal start of railway transport in the country.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q06', 'railway-exam-bank', 'General Awareness', 0, 5, 'What is the Konkan Railway known for?', 'The Konkan Railway, running along India''s western coast through Maharashtra, Goa, and Karnataka, is known for its challenging terrain — it required building hundreds of bridges and tunnels, including the Panval Nadi Viaduct, one of the tallest railway bridges in Asia.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q07', 'railway-exam-bank', 'General Awareness', 0, 6, 'Name the organization responsible for manufacturing railway coaches in Kapurthala, Punjab.', 'Rail Coach Factory (RCF), Kapurthala is one of India''s primary coach-manufacturing units, producing passenger coaches including LHB (Linke Hofmann Busch) coaches for Indian Railways.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q08', 'railway-exam-bank', 'General Awareness', 0, 7, 'What is "Mission Raftaar" associated with Indian Railways?', 'Mission Raftaar was an initiative announced in the 2016-17 Railway Budget aimed at doubling the average speed of freight trains and increasing the average speed of superfast mail/express trains by 25 km/h over five years.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q09', 'railway-exam-bank', 'General Awareness', 0, 8, 'Which is India''s first corporatized railway, running trains between Delhi and Katra?', 'Shri Mata Vaishno Devi Katra is served by the Vande Bharat and other trains, but the first fully corporatized passenger train service is the IRCTC-operated Tejas Express, run as a premium service distinct from standard zonal railway operations.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q10', 'railway-exam-bank', 'General Awareness', 0, 9, 'What is the gauge width of India''s "broad gauge" railway track?', 'Indian broad gauge track has a width of 1,676 mm (5 ft 6 in) between the inner faces of the rails — it is the most widely used gauge across the Indian Railways network.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q11', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 10, 'In a certain code, "RAIL" is written as "SBJM". How is "TRAIN" written in that code?', 'Each letter is shifted forward by one position in the alphabet (R→S, A→B, I→J, L→M). Applying the same rule to TRAIN: T→U, R→S, A→B, I→J, N→O, giving "USBJO".', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q12', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 11, 'Find the next number in the series: 2, 6, 12, 20, 30, ?', 'Each term is n(n+1) for n = 1, 2, 3, 4, 5…: 1×2=2, 2×3=6, 3×4=12, 4×5=20, 5×6=30, so the next term is 6×7 = 42.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q13', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 12, 'Pointing to a photograph, a man said, "She is the daughter of my grandfather''s only son." How is the woman related to the man?', 'The man''s grandfather''s only son is the man''s father (since there''s only one son). So the woman in the photograph is the man''s sister.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q14', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 13, 'Statement: All trains are vehicles. Some vehicles are fast. Conclusion I: Some trains are fast. Conclusion II: All vehicles are trains. Which conclusion(s) follow?', 'Neither conclusion follows. "Some vehicles are fast" doesn''t guarantee those fast vehicles are specifically trains (Conclusion I is unsupported), and the first statement only says trains are a subset of vehicles, not that all vehicles are trains (Conclusion II is false).', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q15', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 14, 'If South-East becomes North, North-East becomes West, then what will North become?', 'Each direction is rotated 135° anticlockwise (South-East → North is a 135° anticlockwise shift). Applying the same 135° anticlockwise rotation to North gives South-West.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q16', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 15, 'Arrange the following in a logical order: 1. Word 2. Sentence 3. Letter 4. Paragraph 5. Phrase', 'The logical building-up order is: Letter → Word → Phrase → Sentence → Paragraph, i.e., 3, 1, 5, 2, 4 — moving from the smallest linguistic unit to the largest.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q17', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 16, 'A is the brother of B. B is the sister of C. C is the father of D. How is A related to D?', 'Since C is the father of D, and A is the sibling of B who is the sibling of C, A is also a sibling of C. That makes A the uncle (or aunt, depending on A''s gender) of D.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q18', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 17, 'Which one does not belong to the group: Mumbai, Delhi, Kolkata, Agra?', 'Agra does not belong — Mumbai, Delhi, and Kolkata are all current or former capital cities (Delhi is the national capital, Kolkata and Mumbai were former capitals), while Agra has never served as a capital.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q19', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 18, 'Complete the analogy: Engine : Train :: Heart : ?', 'Heart : Body (or Human) — just as the engine powers and drives the train forward, the heart pumps blood to power and sustain the human body; both are the central driving/life-sustaining component of their respective systems.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q20', 'railway-exam-bank', 'General Intelligence & Reasoning', 1, 19, 'A clock shows 3:15. What is the angle between the hour and minute hands?', 'At 3:15, the minute hand is at the 3 (90°) and the hour hand has moved a quarter of the way from 3 to 4 (90° + 0.5°×15 = 97.5°). The angle between them is 97.5° − 90° = 7.5°.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q21', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 20, 'A train 150 metres long crosses a platform 250 metres long in 20 seconds. What is the speed of the train in km/h?', 'Total distance covered = length of train + length of platform = 150 + 250 = 400 metres. Speed = distance/time = 400/20 = 20 m/s. Converting to km/h: 20 × (18/5) = 72 km/h.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q22', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 21, 'If the ratio of the ages of A and B is 3:5 and the sum of their ages is 48 years, find A''s age.', 'Let A''s age = 3x and B''s age = 5x. Then 3x + 5x = 48, so 8x = 48, giving x = 6. A''s age = 3 × 6 = 18 years.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q23', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 22, 'A sum of money becomes ₹7,200 in 2 years and ₹8,100 in 3 years at simple interest. Find the principal.', 'The difference between the amounts for year 3 and year 2 (₹8,100 − ₹7,200 = ₹900) is the simple interest for one year. So SI for 2 years = ₹1,800. Principal = Amount after 2 years − SI for 2 years = ₹7,200 − ₹1,800 = ₹5,400.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q24', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 23, 'Find the value of: 15% of 40 + 25% of 60.', '15% of 40 = (15/100)×40 = 6. 25% of 60 = (25/100)×60 = 15. Sum = 6 + 15 = 21.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q25', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 24, 'Two trains run in opposite directions at speeds of 60 km/h and 90 km/h. How long will they take to cross each other if their combined length is 500 metres?', 'Relative speed when moving in opposite directions = 60 + 90 = 150 km/h = 150 × (5/18) = 41.67 m/s (approx). Time = distance/relative speed = 500/41.67 ≈ 12 seconds.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q26', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 25, 'What is the compound interest on ₹10,000 for 2 years at 10% per annum, compounded annually?', 'Amount = P(1 + r/100)^n = 10,000 × (1.1)² = 10,000 × 1.21 = ₹12,100. Compound Interest = Amount − Principal = 12,100 − 10,000 = ₹2,100.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q27', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 26, 'The average of 5 consecutive odd numbers is 61. Find the largest number.', 'For consecutive odd numbers, the average equals the middle (3rd) number, so the middle number is 61. The five numbers are 57, 59, 61, 63, 65 — the largest is 65.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q28', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 27, 'A can complete a work in 12 days and B can complete the same work in 18 days. If they work together, in how many days will the work be completed?', 'A''s one-day work = 1/12, B''s one-day work = 1/18. Combined one-day work = 1/12 + 1/18 = 3/36 + 2/36 = 5/36. Time taken together = 36/5 = 7.2 days.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q29', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 28, 'If the perimeter of a square is 64 cm, find its area.', 'Perimeter = 4 × side, so side = 64/4 = 16 cm. Area = side² = 16² = 256 cm².', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q30', 'railway-exam-bank', 'Mathematics / Numerical Ability', 2, 29, 'A shopkeeper marks an item 25% above the cost price and gives a 10% discount on the marked price. Find his profit percentage.', 'Let cost price = 100. Marked price = 125. Selling price after 10% discount = 125 × 0.9 = 112.5. Profit = 112.5 − 100 = 12.5, so profit percentage = 12.5%.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q31', 'railway-exam-bank', 'General Science', 3, 30, 'What is the SI unit of electric current, and who is it named after?', 'The SI unit of electric current is the Ampere (A), named after the French physicist André-Marie Ampère, a pioneer of classical electromagnetism.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q32', 'railway-exam-bank', 'General Science', 3, 31, 'Which gas is most abundant in the Earth''s atmosphere?', 'Nitrogen (N₂) is the most abundant gas in Earth''s atmosphere, making up approximately 78% of its volume, followed by oxygen at about 21%.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q33', 'railway-exam-bank', 'General Science', 3, 32, 'What is the function of the mitochondria in a cell?', 'Mitochondria are known as the "powerhouse of the cell" — they generate ATP (adenosine triphosphate) through cellular respiration, providing the energy a cell needs for its various functions.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q34', 'railway-exam-bank', 'General Science', 3, 33, 'State Newton''s First Law of Motion.', 'Newton''s First Law (the Law of Inertia) states that an object at rest stays at rest, and an object in motion stays in motion at constant velocity, unless acted upon by an external unbalanced force.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q35', 'railway-exam-bank', 'General Science', 3, 34, 'What is the pH value of a neutral solution, and what does pH measure?', 'A neutral solution has a pH of 7. pH measures the concentration of hydrogen ions (H⁺) in a solution on a scale of 0 to 14, where values below 7 are acidic and above 7 are basic (alkaline).', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q36', 'railway-exam-bank', 'General Science', 3, 35, 'Which part of the human brain is responsible for maintaining balance and coordination?', 'The cerebellum, located at the back of the brain beneath the cerebrum, is primarily responsible for maintaining balance, posture, and coordinating voluntary muscle movements.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q37', 'railway-exam-bank', 'General Science', 3, 36, 'What is the chemical formula of common salt, and what is its chemical name?', 'Common salt has the chemical formula NaCl, and its chemical name is sodium chloride — formed from one sodium ion and one chloride ion.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q38', 'railway-exam-bank', 'General Science', 3, 37, 'Define "isotopes" with an example.', 'Isotopes are atoms of the same element that have the same number of protons but a different number of neutrons, giving them different atomic masses. For example, Carbon-12 and Carbon-14 are both isotopes of carbon, differing in neutron count.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q39', 'railway-exam-bank', 'General Science', 3, 38, 'Why does a diesel locomotive engine not need a separate electric starter motor like a car, and what powers it instead?', 'Diesel locomotives typically use a diesel-electric system: the diesel engine drives a generator/alternator that produces electricity, which then powers traction motors connected to the wheels — the engine itself is usually started using a large battery bank or an auxiliary compressed-air/electric starting system built for its much larger displacement.', '2026-11-12T13:17:07.100Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('railway-q40', 'railway-exam-bank', 'General Science', 3, 39, 'What is the main function of red blood cells (erythrocytes)?', 'Red blood cells primarily transport oxygen from the lungs to tissues throughout the body, and carry carbon dioxide back to the lungs to be exhaled — this is made possible by the hemoglobin protein they contain, which binds to oxygen.', '2026-11-12T13:17:07.100Z');
